template.content:
/**
* 系统名称: SmartWeb平台
* 模块名称: ${modlName}<#if subModlName != "">-${subModlName}</#if>拦截器模块
* 功能描述: ${funcName}控制类
* 类 名 称  : ${ProcClssName}Controller.java
* 软件版权: 北京先进数通信息技术股份公司
* 开发人员: chenyl <br>
* 开发时间: ${functionVersion}<br>
* 系统版本: V1.0.0<br>
** 修改记录:
* 修改日期                            修改人员          修改说明 <br>
* ========     ======  ============================================
* 
* ========     ======  ============================================
*/
package ${packName}.${modlName}<#if subModlName != "">.${subModlName}</#if>.web;

import java.util.List;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.apache.shiro.authz.annotation.RequiresPermissions;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseBody;
import com.adtec.framework.common.util.ParamUtil;
import com.adtec.framework.common.util.SpringContextHolder;
import com.adtec.framework.impl.share.dataset.DatasetService;
import com.adtec.framework.interfaces.share.DatasetColumnType;
import com.adtec.framework.interfaces.share.IDataset;
import com.adtec.framework.exception.BaseException;
import com.adtec.framework.exception.SysErr;
import com.adtec.framework.common.util.DataUtil;
import com.adtec.sys.common.web.BaseController;
import com.adtec.sys.modules.sys.utils.DictUtils;
import com.adtec.sys.modules.sys.utils.UserUtils;
import com.adtec.sys.modules.sys.entity.Office;
import com.adtec.sys.modules.sys.entity.Role;
import com.adtec.sys.modules.sys.entity.User;
import com.adtec.sys.modules.sys.entity.Area;
import com.adtec.sys.modules.sys.service.OfficeService;
import com.adtec.sys.modules.sys.service.SystemService;
import com.adtec.sys.modules.sys.service.AreaService;
<#if hasFileSelect??>
import java.sql.SQLException;
import com.adtec.sys.modules.sys.entity.FileDO;
import com.adtec.sys.modules.sys.service.FileService;
</#if>
import ${packName}.${modlName}<#if subModlName != "">.${subModlName}</#if>.entity.${ProcClssName}DO;
import ${packName}.${modlName}<#if subModlName != "">.${subModlName}</#if>.service.${ProcClssName}Service;

/**
 * ${funcName}Controller
 * @author ${funcCrtr}
 * @version ${functionVersion}
 */
@Controller
@RequestMapping(value = "${r"${adminPath}"}/${urlPrefix}")
public class ${ProcClssName}Controller extends BaseController {

	@Autowired
	private ${ProcClssName}Service ${procClssName}Service;

	<#if hasFileSelect??>
	@Autowired
	private FileService fileService;
	</#if>

	/*首页页面路径*/
	private String PATH = "${PATH}";
	/**
	 * 进入管理页面
	 * @param request
	 * @param response
	 * @return
	 */
	@RequiresPermissions("user")
	@RequestMapping(value ={"manage", ""})
	public String index(HttpServletRequest request, HttpServletResponse response) {
		return PATH+"Manage";
	}

	/**
	 * 列表页面
	 * @param request
	 * @param response
	 * @return
	 */
	@RequiresPermissions("user")
	@RequestMapping(value ={"${procClssName}List"})
	public String ${procClssName}List(HttpServletRequest request, HttpServletResponse response) {
		return PATH+"List";
	}

	/**
	 * 进入新增页面
	 * @param request
	 * @param response
	 * @return
	 */
	@RequiresPermissions("user")
	@RequestMapping(value ={"${procClssName}Add"})
	public String ${procClssName}Add(HttpServletRequest request, HttpServletResponse response) {
		return PATH+"AddForm";
	}

	/**
	 * 进入修改页面
	 * @param request
	 * @param response
	 * @return
	 */
	@RequiresPermissions("user")
	@RequestMapping(value ={"${procClssName}Update"})
	public String ${procClssName}Update(HttpServletRequest request, HttpServletResponse response) {
		return PATH+"UpdateForm";
	}

	/**
	 * 进入详细页面
	 * @param request
	 * @param response
	 * @return
	 */
	@RequiresPermissions("user")
	@RequestMapping(value ={"${procClssName}Detail"})
	public String ${procClssName}Detail(HttpServletRequest request, HttpServletResponse response) {
		return PATH+"DetailForm";
	}

	/**
	* 新增交易
	* @param request
	* @param response
	*/
	@ResponseBody
	@RequiresPermissions("user")
	@RequestMapping(value="insert")
	public void insert(HttpServletRequest request, HttpServletResponse response) {
		IDataset resDs = DatasetService.getInstace().getDataset();
		IDataset reqDs = DatasetService.getInstace().getDataset(request);
		${ProcClssName}DO obj = DatasetService.getInstace().getObject(reqDs, ${ProcClssName}DO.class);
		${procClssName}Service.insert(obj);
		setResponseDataset(request, response, resDs, SysErr.E_SUCCESS, "新增交易成功！");
	}

	/**
	* 修改交易
	* @param request
	* @param response
	*/
	@ResponseBody
	@RequiresPermissions("user")
	@RequestMapping(value="update")
	public void update(HttpServletRequest request, HttpServletResponse response) {
		IDataset resDs = DatasetService.getInstace().getDataset();
		IDataset reqDs = DatasetService.getInstace().getDataset(request);
		${ProcClssName}DO obj = DatasetService.getInstace().getObject(reqDs, ${ProcClssName}DO.class);
		${procClssName}Service.update(obj);
		setResponseDataset(request, response, resDs, SysErr.E_SUCCESS, "更新交易成功！");
	} 

	/**
	* 删除交易
	* @param request
	* @param response
	*/
	@ResponseBody
	@RequiresPermissions("user")
	@RequestMapping(value="delete")
	public void delete(HttpServletRequest request, HttpServletResponse response) {
		IDataset resDs = DatasetService.getInstace().getDataset();
		IDataset reqDs = DatasetService.getInstace().getDataset(request);
		${ProcClssName}DO obj = DatasetService.getInstace().getObject(reqDs, ${ProcClssName}DO.class);
		${procClssName}Service.delete(obj);
		setResponseDataset(request, response, resDs, SysErr.E_SUCCESS, "删除交易成功！");
	}

	/**
	* 列表查询
	* @param request
	* @param response
	*/
	@ResponseBody
	@RequiresPermissions("user")
	@RequestMapping(value="list")
	public void list(HttpServletRequest request, HttpServletResponse response) {
		IDataset resDs = DatasetService.getInstace().getDataset();
		IDataset reqDs = DatasetService.getInstace().getDataset(request);
		${ProcClssName}DO obj = DatasetService.getInstace().getObject(reqDs, ${ProcClssName}DO.class);
		int start = reqDs.getInt("start");
		int limit = reqDs.getInt("pageSize");
		List<${ProcClssName}DO> list = ${procClssName}Service.list(obj, start, limit);
		int total = ${procClssName}Service.getTotal(obj);
		resDs = DatasetService.getInstace().getDataset(list,${ProcClssName}DO.class);
		chgDict(resDs, true);
		resDs.setTotalCount(total);
		setResponseDataset(request, response, resDs, SysErr.E_SUCCESS, "列表查询交易成功！");
	} 

	/**
	* 明细查询
	* @param request
	* @param response
	*/
	@ResponseBody
	@RequestMapping(value="get")
	public void get(HttpServletRequest request, HttpServletResponse response) {
		IDataset reqDs = DatasetService.getInstace().getDataset(request);
		<#if table.pkList?? && (table.pkList?size>0)>
			<#assign count=0>
			<#list table.columnList as c>
				<#if c.mainKeyFlg?? && c.mainKeyFlg == "1">
		<#assign count=count+1>
		${c.simpleJavaTp} ${c.simpleJavaField} = reqDs.get${c.simpleJavaTp}("${c.simpleJavaField}");
					<#if c.simpleJavaTp=="String">
		if (DataUtil.isNullStr(${c.simpleJavaField})) {
			throw new BaseException(SysErr.E_IN_NULL, "输入项[${c.simpleJavaField}]不能空！");
		}		
					<#else>
		if (null==${c.simpleJavaField}) {
			throw new BaseException(SysErr.E_IN_NULL, "输入项[${c.simpleJavaField}]不能空！");
		}		
					</#if>
				</#if>
			</#list>
		<#else>
		String id = reqDs.getString("id");
		if (DataUtil.isNullStr(id)) {
			throw new BaseException(SysErr.E_MESSAGE, "输入项[id]不能空！");
		}
		</#if>

		${ProcClssName}DO obj = ${procClssName}Service.get(<#if table.pkList?? && (table.pkList?size>0)><#assign count=0><#list table.columnList as c><#if c.mainKeyFlg?? && c.mainKeyFlg == "1"><#assign count=count+1>${c.simpleJavaField}<#if (count<table.pkList?size)>, </#if></#if></#list><#else>id</#if>);
		IDataset resDs = DatasetService.getInstace().getDataset(obj, ${ProcClssName}DO.class);
		chgDict(resDs, false);
		setResponseDataset(request, response, resDs, SysErr.E_SUCCESS, "明细查询交易成功！");
	}

	/**
	 * 数字字典转换
	 * @param ds
	 * @param isAction
	 */
	private void chgDict(IDataset ds, boolean isAction){
		if(null==ds){
			return;
		}
		SystemService systemService = SpringContextHolder.getBean("systemService");
		OfficeService officeService = SpringContextHolder.getBean("officeService");
		AreaService areaService = SpringContextHolder.getBean("areaService");
		<#list table.columnList as c>
			<#if c.listFlg?? && c.listFlg == "1">
				<#if c.dpyTp == "select" || c.dpyTp == "checkbox" || c.dpyTp == "radiobox">
					<#if c.dictTp??>
		//新增${c.tabDesc}中文描述列
		ds.addColumn("${c.javaFieldId}Str", DatasetColumnType.DS_STRING);
					</#if>
				<#elseif c.dpyTp == "userselect" || c.dpyTp == "officeselect" || c.dpyTp == "areaselect">
		//新增${c.tabDesc}中文名称列
		ds.addColumn("${c.javaFieldId}Name", DatasetColumnType.DS_STRING);
				</#if>						
			</#if>
		</#list>
		if(isAction){
			//新增操作描述列
			ds.addColumn("action", DatasetColumnType.DS_STRING);
		}
		ds.beforeFirst();
		while(ds.hasNext()){
			ds.next();
			<#list table.columnList as c>
				<#if c.listFlg?? && c.listFlg == "1">
					<#if c.dpyTp == "select" || c.dpyTp == "checkbox" || c.dpyTp == "radiobox">
						<#if c.dictTp??>
			//更新${c.tabDesc}中文描述
			String ${c.javaFieldId} = ds.getString("${c.javaFieldId}");
			ds.updateString("${c.javaFieldId}Str", DictUtils.getDictLabels(${c.javaFieldId}, "${c.dictTp}", ${c.javaFieldId}));
						</#if>
					<#elseif c.dpyTp == "fileselect">
			// 更新${c.javaFieldId}的图片id转换成url
			String ${c.javaFieldId} = ds.getString("${c.javaFieldId}");
			if(!DataUtil.isNullStr(${c.javaFieldId})){
				// 获取${c.javaFieldId}的图片的访问路径
				FileDO fileDO = new FileDO();
				fileDO = fileService.get(${c.javaFieldId});
				ds.updateString("${c.javaFieldId}", fileDO.getPrevPath());
			}			
					<#elseif c.dpyTp == "userselect">
			//更新${c.tabDesc}中文名称
			String ${c.javaFieldId} = ds.getString("${c.javaFieldId}");
			String ${c.javaFieldId}Name = ${c.javaFieldId};
			User ${c.javaFieldId}User = systemService.getUser(${c.javaFieldId});
			if(null!=${c.javaFieldId}User){
					${c.javaFieldId}Name = ${c.javaFieldId}User.getName();
			}
			ds.updateString("${c.javaFieldId}Name", ${c.javaFieldId}Name);
					<#elseif c.dpyTp == "userselect">
			//更新${c.tabDesc}中文名称
			String ${c.javaFieldId} = ds.getString("${c.javaFieldId}");
			String ${c.javaFieldId}Name = ${c.javaFieldId};
			User ${c.javaFieldId}User = systemService.getUser(${c.javaFieldId});
			if(null!=${c.javaFieldId}User){
					${c.javaFieldId}Name = ${c.javaFieldId}User.getName();
			}
			ds.updateString("${c.javaFieldId}Name", ${c.javaFieldId}Name);
					<#elseif c.dpyTp == "officeselect">
			//更新${c.tabDesc}中文名称
			String ${c.javaFieldId} = ds.getString("${c.javaFieldId}");
			String ${c.javaFieldId}Name = ${c.javaFieldId};
			Office ${c.javaFieldId}Office = officeService.get(${c.javaFieldId});
			if(null!=${c.javaFieldId}Office){
				${c.javaFieldId}Name = ${c.javaFieldId}Office.getName();
			}
			ds.updateString("${c.javaFieldId}Name", ${c.javaFieldId}Name);
					<#elseif c.dpyTp == "areaselect">
			//更新${c.tabDesc}中文名称
			String ${c.javaFieldId} = ds.getString("${c.javaFieldId}");
			String ${c.javaFieldId}Name = ${c.javaFieldId};
			Area  ${c.javaFieldId}Area = areaService.get(${c.javaFieldId});
			if(null!=${c.javaFieldId}Area){
				${c.javaFieldId}Name = ${c.javaFieldId}Area.getName();
			}
			ds.updateString("${c.javaFieldId}Name", ${c.javaFieldId}Name);
					<#elseif c.dpyTp == "roleselect">
			//更新${c.tabDesc}中文名称
			String ${c.javaFieldId} = ds.getString("${c.javaFieldId}");
			String ${c.javaFieldId}Name = ${c.javaFieldId};
			Role ${c.javaFieldId}Role = systemService.getRole(${c.javaFieldId});
			if(null!=${c.javaFieldId}Role){
				${c.javaFieldId}Name = ${c.javaFieldId}Role.getName();
			}
			ds.updateString("${c.javaFieldId}Name", ${c.javaFieldId}Name);
					</#if>
				</#if>
			</#list>

			if(isAction){
				/*添加相关操作按钮*/
				StringBuffer action = new StringBuffer();
				action.append("	<a href=\"JavaScript:void(0);\" onClick=\"detail(" <#if table.pkList?? && (table.pkList?size>0)><#assign count=0><#list table.columnList as c><#if c.mainKeyFlg?? && c.mainKeyFlg == "1"><#assign count=count+1>+"'"+ds.get${c.simpleJavaTp}("${c.simpleJavaField}")<#if (count<table.pkList?size)>+"', "<#else>+"'" </#if></#if></#list><#else>"'"+ds.getString("id")+"'"</#if>+ ")\" >详情</a>");
				action.append("	<a href=\"JavaScript:void(0);\" onClick=\"update(" <#if table.pkList?? && (table.pkList?size>0)><#assign count=0><#list table.columnList as c><#if c.mainKeyFlg?? && c.mainKeyFlg == "1"><#assign count=count+1>+"'"+ds.get${c.simpleJavaTp}("${c.simpleJavaField}")<#if (count<table.pkList?size)>+"', "<#else>+"'" </#if></#if></#list><#else>"'"+ds.getString("id")+"'"</#if>+ ")\" >修改</a>");
				action.append("	<a href=\"JavaScript:void(0);\" onClick=\"del(" <#if table.pkList?? && (table.pkList?size>0)><#assign count=0><#list table.columnList as c><#if c.mainKeyFlg?? && c.mainKeyFlg == "1"><#assign count=count+1>+"'"+ds.get${c.simpleJavaTp}("${c.simpleJavaField}")<#if (count<table.pkList?size)>+"', "<#else>+"'" </#if></#if></#list><#else>"'"+ds.getString("id")+"'"</#if>+ ")\" >删除</a>");
				ds.updateString("action", action.toString());
			}
		}
	}
}
